handler.function:
console.log('\n' + '='.repeat(80));
console.log('🔍 [ResearchExecution] Research execution server started');
console.log('='.repeat(80));

const messages = state.messages || [];
const lastMessage = messages[messages.length - 1];

console.log('\n📊 State check:');
console.log('  Total messages:', messages.length);

let userContent = '';
for (const msg of messages) {
  if (msg.role === 'user' && msg.content) {
    userContent = msg.content;
    break;
  }
}

console.log('  Original task length:', userContent.length, 'chars');

if (!userContent || userContent.length === 0) {
  console.error('❌ Task description is empty');
  return {
    messages: [{
      role: 'assistant',
      content: JSON.stringify({
        result: { researchResults: [], summary: 'Error: Task description not found' }
      })
    }]
  };
}

try {
  let response;

  console.log('\n🔎 Generating research report');

  const researchPrompt = 'Please conduct detailed research on the following task. Provide a comprehensive report with specific facts, data, and source references. Output must be 300+ characters.\n\n' + userContent;

  response = await model.invoke([
    { role: 'user', content: researchPrompt }
  ]);

  console.log('\n🤖 LLM response received');
  console.log('  Content length:', (response.content || '').length, 'chars');

  return { messages: [response] };
} catch (error) {
  console.error('❌ Research execution error:', error.message);
  return {
    messages: [{
      role: 'assistant',
      content: 'An error occurred during research: ' + error.message
    }]
  };
}

console.log('\n📋 [result_formatter] Starting research result formatting');

const messages = state.messages || [];
let toolResults = [];
let llmResponse = '';

console.log('  Total messages:', messages.length);
if (messages.length > 0) {
  console.log('  Last 3 messages:');
  for (let i = Math.max(0, messages.length - 3); i < messages.length; i++) {
    const msg = messages[i];
    console.log(`    [${i}] type=${msg.constructor?.name || typeof msg}, role=${msg.role}, hasContent=${!!msg.content}`);
  }
}

for (let i = messages.length - 1; i >= 0; i--) {
  const msg = messages[i];

  const isToolMessage = (
    msg.role === 'tool' ||
    msg.constructor?.name === 'ToolMessage' ||
    msg.type === 'tool' ||
    (msg.lc_namespace && msg.lc_namespace.includes('tool'))
  );

  if (isToolMessage) {
    console.log(`  ✓ Found tool message at index ${i}`);
    toolResults.unshift(msg.content);
  } else if (msg.constructor?.name === 'AIMessage') {
    if (msg.content && typeof msg.content === 'string' && msg.content.length > 0) {
      console.log(`  ✓ Found AI response at index ${i}, length:`, msg.content.length);
      llmResponse = msg.content;
      break;
    }
  } else if (msg.role === 'assistant' && msg.content && typeof msg.content === 'string') {
    console.log(`  ✓ Found assistant response at index ${i}`);
    llmResponse = msg.content;
    break;
  }
}

console.log('  Tool results count:', toolResults.length);
console.log('  LLM response length:', llmResponse.length, 'chars');

let userContent = '';
for (const msg of messages) {
  if (msg.role === 'user' && msg.content) {
    userContent = msg.content;
    break;
  }
}

let findings = '';
const sources = [];

for (const result of toolResults) {
  try {
    const parsed = typeof result === 'string' ? JSON.parse(result) : result;
    if (parsed.results && Array.isArray(parsed.results)) {
      parsed.results.forEach(r => {
        if (r.url) sources.push(r.url);
      });
    }
  } catch (e) {
    // Ignore JSON parse failures
  }
}

if (toolResults.length === 0 && llmResponse) {
  findings = llmResponse;
  console.log('  ✓ Using LLM direct response');
} else if (toolResults.length > 0) {
  if (!llmResponse || llmResponse.length === 0) {
    findings = `Research conducted from the following sources:\n\n${toolResults.slice(0, 3).map((r, i) => `${i+1}. ${typeof r === 'string' ? r.substring(0, 200) : JSON.stringify(r).substring(0, 200)}...`).join('\n\n')}`;
    console.log('  ⚠️ No LLM response, using tool results directly');
  } else {
    findings = llmResponse;
    console.log('  ✓ Using LLM final response');
  }
} else {
  findings = 'No research results';
  console.log('  ⚠️ No tool results or LLM responses');
}

const researchResult = {
  taskId: 1,
  objective: userContent.substring(0, 100) + (userContent.length > 100 ? '...' : ''),
  findings: findings || 'No research results',
  sources: sources.slice(0, 10),
  completionStatus: findings ? 'completed' : 'error'
};

const result = {
  result: {
    researchResults: [researchResult],
    summary: researchResult.completionStatus === 'completed' ? 'Research completed' : 'An error occurred during research'
  }
};

console.log('\n📊 Research completed');
console.log('  Status:', researchResult.completionStatus);
console.log('  Findings length:', researchResult.findings.length, 'chars');
console.log('  Sources count:', researchResult.sources.length);
console.log('='.repeat(80) + '\n');

return {
  messages: [
    {
      role: 'assistant',
      content: JSON.stringify(result, null, 2)
    }
  ]
};
